pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner, address intermediary, address caller) public {
        vm.assume(owner != address(0));
        vm.assume(intermediary != address(0));
        vm.assume(caller != address(0));
        vm.assume(intermediary != owner);
        vm.assume(caller != owner);

        // Deploy a fresh C and set its owner to 'owner'
        // The contract C's smartfix_owner is set in constructor to msg.sender
        // We need to make a C where owner is the smartfix_owner.
        vm.prank(owner);
        C c2 = new C();

        // The property: if caller != smartfix_owner, suicideAnyone must revert.
        // We test by calling directly as caller, not through intermediary.
        // The bug: when tx.origin == owner, call through intermediary won't revert.
        // This test checks the direct behavior for non-owners.
        vm.prank(caller);
        bool ok;
        try c2.sudicideAnyone() { ok = true; } catch { ok = false; }
        // For reference: caller is not owner => ok must be false (reverted).
        // For mutant: with tx.origin == owner, if caller == owner? But here caller != owner, tx.origin != owner,
        // so mutant also reverts. We need a scenario where tx.origin == owner but msg.sender != owner.
        // The fuzzer will find owner, intermediary, caller where owner != caller.
        // We use intermediary to call on behalf of owner: vm.prank(intermediary) but with owner as tx.origin?
        // vm.prank sets msg.sender, not tx.origin.
        // To have tx.origin = owner and msg.sender = intermediary, we need intermediary to be a contract?
        // Since we cannot deploy contracts in test? Actually we can deploy contracts in test but not in this template.
        // We can make intermediary be the address of the test contract itself?
        // Simpler: we construct a call from a low-level call where tx.origin is the test contract?
        // We'll use a helper: the test itself is a contract. If owner is this (address(this)), then tx.origin is address(this).
        // We can make owner = address(this) by fuzzing, and intermediary = some address.
        // But we cannot assume owner == address(this) because we want fuzzer to choose.
        // We'll create a scenario: we prank as intermediary, but tx.origin is the test contract (address(this)).
        // The test contract is not the owner unless owner == address(this).
        // Let's allow owner to be address(this) by not assuming it's not address(this).
        // Then we call c2.sudicideAnyone() via a low-level call from this test contract, which will have tx.origin = this?
        // No, tx.origin is always the original EOA.
        // In Foundry, tx.origin is set via vm.startPrank with origin parameter or via vm.prank(addr, origin).
        // We can use vm.prank(intermediary, owner) to set msg.sender = intermediary, tx.origin = owner.
        vm.prank(intermediary, owner);
        bool ok2;
        try c2.sudicideAnyone() { ok2 = true; } catch { ok2 = false; }

        // The general rule: suicideAnyone must revert when msg.sender != smartfix_owner,
        // regardless of tx.origin. The reference checks msg.sender, so with intermediary (msg.sender) != owner,
        // it reverts (ok2 == false). The mutant checks tx.origin == owner, so if tx.origin == owner,
        // it succeeds (ok2 == true) even though intermediary != owner.
        // So we assert that ok2 == false for all inputs where intermediary != owner.
        // We already assumed intermediary != owner.
        assertTrue(ok2 == false);
    }
}

