pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address origin) public {
        vm.assume(caller != c.smartfix_owner());
        vm.assume(origin == c.smartfix_owner());
        vm.assume(caller != origin);

        vm.prank(origin);
        vm.startPrank(caller, origin);

        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }

        vm.stopPrank();

        bool afterCall = address(c).code.length > 0;
        assertTrue(reverted || !afterCall);
    }
}

