pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address msgSender, uint104 payment) public {
        vm.assume(msgSender != address(0));
        vm.assume(payment > 0);
        // fund the contract
        vm.deal(msgSender, payment);
        vm.prank(msgSender);
        (bool funded,) = address(c).call{value: payment}("");
        vm.assume(funded);
        // record caller balance before
        uint256 balBefore = msgSender.balance;
        uint256 contractBalBefore = address(c).balance;
        // msgSender must be the owner to call sudicideAnyone
        // We set the deployment so that smartfix_owner is 
        // whoever deployed. We cannot change that, but we can
        // make msgSender be the deployer by not pre-setting.
        // The test deploys C in setUp(), so setUp() caller is the test contract itself.
        // We cannot prank as real owner unless we are the test contract.
        // Instead, we can use the fact that smartfix_owner = address(this).
        // So only address(this) can call sudicideAnyone.
        // To let the fuzzer pick msgSender, we must ensure msgSender == smartfix_owner.
        // This is too restrictive; we can instead check that if msgSender is owner,
        // then the balance increase property holds.
        // Actually, the fuzzer provides msgSender; we cannot change it.
        // We can vm.assume(msgSender == c.smartfix_owner()) to stick to admissible inputs
        // where the call succeeds.
        vm.assume(msgSender == c.smartfix_owner());
        vm.prank(msgSender);
        try c.sudicideAnyone() { } catch { }
        // After successful call, the caller's balance must be greater than before
        // by at least the contract's balance before.
        // The bug sends to address(0), so msgSender.balance remains balBefore.
        // The reference sends to msgSender, so msgSender.balance >= balBefore + contractBalBefore.
        assertTrue(msgSender.balance >= balBefore + contractBalBefore);
    }
}
